package artifact

import (
	"errors"
	"strings"
	"unicode"

	"github.com/parth10-05/fleetforge/internal/domain/value"
)

const SyntheticFirmwareMediaType = "application/octet-stream"

var ErrInvalidUploadMetadata = errors.New("invalid artifact upload metadata")

// UploadMetadata contains only the bounded, non-secret client declaration.
// DisplayName is never used as an object key; storage identity is generated by
// the application from the artifact ID and later bound version.
type UploadMetadata struct {
	displayName string
	mediaType   string
	size        int64
	digest      value.SHA256Digest
}

func NewUploadMetadata(displayName, mediaType string, size int64, digest value.SHA256Digest) (UploadMetadata, error) {
	if !validDisplayName(displayName) || mediaType != SyntheticFirmwareMediaType || size <= 0 || size > maxArtifactSize || digest.IsZero() {
		return UploadMetadata{}, ErrInvalidUploadMetadata
	}
	return UploadMetadata{displayName: displayName, mediaType: mediaType, size: size, digest: digest}, nil
}

func (metadata UploadMetadata) DisplayName() string        { return metadata.displayName }
func (metadata UploadMetadata) MediaType() string          { return metadata.mediaType }
func (metadata UploadMetadata) Size() int64                { return metadata.size }
func (metadata UploadMetadata) Digest() value.SHA256Digest { return metadata.digest }

func validDisplayName(raw string) bool {
	if len(raw) == 0 || len(raw) > 256 || strings.ContainsAny(raw, "/\\\x00") {
		return false
	}
	for _, character := range raw {
		if unicode.IsControl(character) {
			return false
		}
	}
	return true
}
